/// Die Marke als Rohdaten (Zwilling von `marke-daten.ts` in
/// `@kreiseck/kasseneck-api` ab 0.26.0): ein 1-Bit-Raster je Druckbreite --
/// MSB zuerst, jede Zeile auf volle Bytes aufgefuellt, base64-kodiert.
///
/// Gezogen aus dem Vertrag (`tool/zwillinge.sh ziehen`,
/// `test/fixtures/vertrag/marke.json`) -- nicht von Hand abgetippt und nicht
/// neu gerechnet. `test/marke_test.dart` beweist, dass diese Datei mit dem
/// Vertrag uebereinstimmt. Wer die Marke aendert, aendert zuerst das
/// JS-Paket und zieht hier neu (`docs/specs/2026-09-21-marke-einheitlich-design.md`, § 3.4).
library;

import 'package:kasseneck_api/enums/keck_paper_size.dart';

/// Ein gepacktes Raster: Masse plus die Bits selbst.
class MarkeRasterDaten {
  final int breite;
  final int hoehe;

  /// Rasterzeilen als Bits, MSB zuerst, je Zeile auf volle Bytes aufgefuellt; base64.
  final String bits;

  const MarkeRasterDaten({required this.breite, required this.hoehe, required this.bits});
}

/// Das Raster der Marke, je Papierbreite -- fertig, nichts wird zur Laufzeit
/// gerastert oder skaliert (siehe [markeBild]).
const Map<KeckPaperSize, MarkeRasterDaten> markeRaster = {
  KeckPaperSize.mm80: MarkeRasterDaten(breite: 352, hoehe: 51, bits: ""),
  KeckPaperSize.mm58: MarkeRasterDaten(breite: 234, hoehe: 34, bits: ""),
};
